CREATE TABLE IF NOT EXISTS tutor_batches (id CHAR(36) PRIMARY KEY, tutor_id CHAR(36) NOT NULL, name VARCHAR(150) NOT NULL, course VARCHAR(80) NOT NULL, level VARCHAR(100) NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, INDEX idx_tutor_batches_tutor (tutor_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS tutor_batch_students (batch_id CHAR(36) NOT NULL, student_id CHAR(36) NOT NULL, assigned_at DATETIME NOT NULL, PRIMARY KEY (batch_id, student_id), UNIQUE KEY uq_tutor_batch_student (student_id), INDEX idx_batch_students_student (student_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS tutor_batch_classes (id CHAR(36) PRIMARY KEY, batch_id CHAR(36) NOT NULL, topic VARCHAR(200) NOT NULL, class_date DATE NULL, class_time TIME NULL, meeting_link VARCHAR(1000) NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, INDEX idx_batch_classes_batch (batch_id), INDEX idx_batch_classes_date (class_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS tutor_class_attendance (class_id CHAR(36) NOT NULL, student_id CHAR(36) NOT NULL, is_present TINYINT(1) NOT NULL DEFAULT 0, updated_at DATETIME NOT NULL, PRIMARY KEY (class_id, student_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
